const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');

function createTenantClient(tenantId) {
  return new PrismaClient().$extends({
    query: {
      note: {
        async findMany({ args, query }) {
          args.where = { ...args.where, tenantId };
          return query(args);
