    path.join(__dirname, 'rls_result.json'),
    JSON.stringify(result)
  );

  console.log('Result:', result);

  await acme.$disconnect();
  await globex.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
